<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Throwable; use Illuminate\Console\Command; use Carbon\CarbonImmutable; use Pterodactyl\Models\Dezerx\RecycledFile; use Pterodactyl\Services\Dezerx\RecycleBin; class PruneRecycleBins extends Command { protected $signature = 'dezerx:prune-recycle-bins'; protected $description = 'Permanently deletes recycle bin entries whose retention has run out.'; public function handle(RecycleBin $bin): int { $expired = RecycledFile::query() ->with('server') ->where('expires_at', '<=', CarbonImmutable::now()) ->get(); if ($expired->isEmpty()) { return self::SUCCESS; } $removed = 0; foreach ($expired as $item) { $server = $item->server; if ($server === null) { $item->delete(); continue; } try { $bin->purge($server, $item); $removed++; } catch (Throwable $exception) { $this->warn("Could not empty {$item->name} for server {$server->uuid}: {$exception->getMessage()}"); } } $this->info("Removed $removed expired recycle bin " . ($removed === 1 ? 'entry.' : 'entries.')); return self::SUCCESS; } } 